def previousWithOneSwap(nums):
    a = list(nums)
    n = len(a)
    for i in range(n - 2, -1, -1):
        if a[i] > a[i + 1]:
            best = -1
            for j in range(i + 1, n):
                if a[j] < a[i] and (best == -1 or a[j] > a[best]):
                    best = j
            a[i], a[best] = a[best], a[i]
            return a
    return a
